using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.SignalR;

namespace ChatServer.Hubs
{
    public class RoomPermissionEntry
    {
        public string UserId { get; set; }
        public string RoomId { get; set; }
        public int AccessLevel { get; set; } // 0=none, 1=read, 2=write, 3=admin
        public DateTime GrantedAt { get; set; }
        public DateTime? RevokedAt { get; set; }
        public bool IsActive => RevokedAt == null;
    }

    public class RoomMetadata
    {
        public string RoomId { get; set; }
        public string OwnerId { get; set; }
        public bool IsPrivate { get; set; }
        public int MaxMembers { get; set; }
        public HashSet<string> BannedUsers { get; set; } = new();
    }

    public interface IPermissionStore
    {
        Task<RoomPermissionEntry> GetPermissionAsync(string userId, string roomId);
        Task SetPermissionAsync(RoomPermissionEntry entry);
        Task<RoomMetadata> GetRoomMetadataAsync(string roomId);
    }

    public class DistributedPermissionStore : IPermissionStore
    {
        private readonly ConcurrentDictionary<string, RoomPermissionEntry> _permissions = new();
        private readonly ConcurrentDictionary<string, RoomMetadata> _rooms = new();

        private string MakeKey(string userId, string roomId) => $"{userId}:{roomId}";

        public Task<RoomPermissionEntry> GetPermissionAsync(string userId, string roomId)
        {
            _permissions.TryGetValue(MakeKey(userId, roomId), out var entry);
            return Task.FromResult(entry);
        }

        public Task SetPermissionAsync(RoomPermissionEntry entry)
        {
            _permissions[MakeKey(entry.UserId, entry.RoomId)] = entry;
            return Task.CompletedTask;
        }

        public Task<RoomMetadata> GetRoomMetadataAsync(string roomId)
        {
            _rooms.TryGetValue(roomId, out var meta);
            return Task.FromResult(meta);
        }
    }

    public class ChatHub : Hub
    {
        private readonly IPermissionStore _permissionStore;
        private static readonly ConcurrentDictionary<string, SemaphoreSlim> _roomLocks = new();
        private static readonly ConcurrentDictionary<string, HashSet<string>> _roomMembers = new();

        public ChatHub(IPermissionStore permissionStore)
        {
            _permissionStore = permissionStore;
        }

        private SemaphoreSlim GetRoomLock(string roomId)
        {
            return _roomLocks.GetOrAdd(roomId, _ => new SemaphoreSlim(1, 1));
        }

        /// <summary>
        /// Validates user access and joins them to a chat room.
        /// Uses distributed permission store for Kubernetes pod consistency.
        /// </summary>
        public async Task JoinRoom(string roomId)
        {
            var userId = Context.UserIdentifier;
            if (string.IsNullOrEmpty(userId) || string.IsNullOrEmpty(roomId))
            {
                await Clients.Caller.SendAsync("Error", "Invalid parameters");
                return;
            }

            // Phase 1: Check permissions from distributed store
            var permission = await _permissionStore.GetPermissionAsync(userId, roomId);
            var roomMeta = await _permissionStore.GetRoomMetadataAsync(roomId);

            if (roomMeta == null)
            {
                await Clients.Caller.SendAsync("Error", "Room not found");
                return;
            }

            if (roomMeta.BannedUsers.Contains(userId))
            {
                await Clients.Caller.SendAsync("Error", "You are banned from this room");
                return;
            }

            if (roomMeta.IsPrivate && (permission == null || !permission.IsActive || permission.AccessLevel < 1))
            {
                await Clients.Caller.SendAsync("Error", "Access denied");
                return;
            }

            // Phase 2: Acquire room lock and add member
            var roomLock = GetRoomLock(roomId);
            await roomLock.WaitAsync();
            try
            {
                var members = _roomMembers.GetOrAdd(roomId, _ => new HashSet<string>());

                if (members.Count >= roomMeta.MaxMembers)
                {
                    await Clients.Caller.SendAsync("Error", "Room is full");
                    return;
                }

                // Note: permission was validated above, proceed with join
                members.Add(userId);
                await Groups.AddToGroupAsync(Context.ConnectionId, roomId);
                await Clients.Group(roomId).SendAsync("UserJoined", userId);
            }
            finally
            {
                roomLock.Release();
            }
        }

        /// <summary>
        /// Sends a message to a room after verifying write access.
        /// </summary>
        public async Task SendMessage(string roomId, string message)
        {
            var userId = Context.UserIdentifier;
            if (string.IsNullOrEmpty(userId) || string.IsNullOrEmpty(roomId))
                return;

            if (string.IsNullOrEmpty(message) || message.Length > 4096)
                return;

            // Sanitize message content
            message = SanitizeMessage(message);

            // Verify write permission
            var permission = await _permissionStore.GetPermissionAsync(userId, roomId);
            if (permission == null || !permission.IsActive || permission.AccessLevel < 2)
            {
                await Clients.Caller.SendAsync("Error", "Write access denied");
                return;
            }

            var roomMeta = await _permissionStore.GetRoomMetadataAsync(roomId);
            if (roomMeta != null && roomMeta.BannedUsers.Contains(userId))
            {
                await Clients.Caller.SendAsync("Error", "You are banned");
                return;
            }

            await Clients.Group(roomId).SendAsync("ReceiveMessage", userId, message, DateTime.UtcNow);
        }

        /// <summary>
        /// Admin action: ban a user from a room. Validates admin permission
        /// then revokes target's access and removes them.
        /// </summary>
        public async Task BanUser(string roomId, string targetUserId)
        {
            var adminId = Context.UserIdentifier;
            if (string.IsNullOrEmpty(adminId) || string.IsNullOrEmpty(roomId) || string.IsNullOrEmpty(targetUserId))
                return;

            // Verify admin has level 3 access
            var adminPermission = await _permissionStore.GetPermissionAsync(adminId, roomId);
            if (adminPermission == null || !adminPermission.IsActive || adminPermission.AccessLevel < 3)
            {
                await Clients.Caller.SendAsync("Error", "Admin access required");
                return;
            }

            var roomMeta = await _permissionStore.GetRoomMetadataAsync(roomId);
            if (roomMeta == null)
                return;

            // Cannot ban the room owner
            if (targetUserId == roomMeta.OwnerId)
            {
                await Clients.Caller.SendAsync("Error", "Cannot ban room owner");
                return;
            }

            // Revoke target's permission
            var targetPermission = await _permissionStore.GetPermissionAsync(targetUserId, roomId);
            if (targetPermission != null)
            {
                targetPermission.RevokedAt = DateTime.UtcNow;
                await _permissionStore.SetPermissionAsync(targetPermission);
            }

            // Add to ban list and remove from room
            var roomLock = GetRoomLock(roomId);
            await roomLock.WaitAsync();
            try
            {
                roomMeta.BannedUsers.Add(targetUserId);
                if (_roomMembers.TryGetValue(roomId, out var members))
                {
                    members.Remove(targetUserId);
                }
            }
            finally
            {
                roomLock.Release();
            }

            await Clients.Group(roomId).SendAsync("UserBanned", targetUserId);
        }

        private string SanitizeMessage(string input)
        {
            if (input == null) return string.Empty;
            return input.Replace("<", "&lt;").Replace(">", "&gt;").Replace("&", "&amp;");
        }

        public override async Task OnDisconnectedAsync(Exception exception)
        {
            var userId = Context.UserIdentifier;
            if (!string.IsNullOrEmpty(userId))
            {
                foreach (var kvp in _roomMembers)
                {
                    var roomLock = GetRoomLock(kvp.Key);
                    await roomLock.WaitAsync();
                    try
                    {
                        kvp.Value.Remove(userId);
                    }
                    finally
                    {
                        roomLock.Release();
                    }
                }
            }
            await base.OnDisconnectedAsync(exception);
        }
    }
}
